exercises.solution:
def docker_run_cmd(image, ports=None, env=None, rm=True):
    parts = ["docker", "run"]
    if rm:
        parts.append("--rm")
    for host, container in (ports or {}).items():
        parts.append(f"-p {host}:{container}")
    for key, value in (env or {}).items():
        parts.append(f"-e {key}={value}")
    parts.append(image)
    return " ".join(parts)

